package com.lianxibu.site.service.jobs;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import java.time.*;
import java.time.format.DateTimeFormatterBuilder;
import java.util.*;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

/** Permanent complete original-day member references. Receipt values alone grant no allocation or input authority. */
public final class CatalogDayAnalysisReservationLedger {
    public record Member(String itemId,String runId,String sourceId,String rootId,String inputHash,String bodyHash,String fragmentResultHash,String finalResultHash,long revision){@Override public String toString(){return "CatalogDayReservationMember[redacted]";} }
    public static final class Stored {
        private final String json,key,category,entity,logical,intent,trigger,closure,grouping;private final LocalDate day;private final long generation,before,after;private final Instant time;private final List<Member> members;
        private Stored(JsonNode n,List<Member> members){json=JdbcFrozenInputs.canonical(n);key=text(n,"reservation_key");category=text(n,"category");entity=text(n,"entity_id");logical=text(n,"logical_key");intent=text(n,"intent_id");trigger=text(n,"trigger");closure=text(n,"closure_hash");grouping=text(n,"grouping_hash");day=WireValues.businessDate(n.get("business_date"));generation=number(n,"generation");before=number(n,"entity_revision_before");after=number(n,"entity_revision_after");time=WireValues.utcMicroseconds(n.get("reserved_at"));this.members=List.copyOf(members);}
        public String json(){return json;}public String reservationKey(){return key;}public String category(){return category;}public String entityId(){return entity;}public String logicalKey(){return logical;}public String intentId(){return intent;}public String trigger(){return trigger;}public String closureHash(){return closure;}public String groupingHash(){return grouping;}public LocalDate day(){return day;}public long generation(){return generation;}public long entityRevisionBefore(){return before;}public long entityRevisionAfter(){return after;}public Instant reservedAt(){return time;}public List<Member> members(){return members;}
        @Override public String toString(){return "StoredCatalogDayAnalysisReservation[redacted]";}
    }
    private final JdbcCatalogDayAnalysisReservations storage;private final String category;
    public CatalogDayAnalysisReservationLedger(JdbcCatalogDayAnalysisReservations storage,String category){this.storage=Objects.requireNonNull(storage);this.category=category(category);}
    public Stored read(LocalDate day,String entity){return decode(storage.read(JdbcCatalogDayAnalysisReservations.key(category,day,entity)),day,entity);}
    public Stored lockAndRead(LocalDate day,String entity){return decode(storage.lockAndRead(JdbcCatalogDayAnalysisReservations.key(category,day,entity)),day,entity);}
    /** Strict proposed metadata only; native entity/intent and issuer permission must be verified by its caller. */
    public static Stored propose(CatalogDayAnalysisEligibilityService.Captured day,CatalogDayAnalysisEligibilityService.Selection selection,long after,Instant now){
        Objects.requireNonNull(day);Objects.requireNonNull(selection);var evidence=day.evidence();if(!day.selected().contains(selection)||now==null||now.isBefore(evidence.original().cutoff()))throw invalid();var entity=selection.entity();String category=category(entity.category());var n=JsonMapper.shared().createObjectNode().put("schema_version","catalog-day-analysis-reservation-v1").put("category",category).put("business_date",evidence.original().day().toString()).put("entity_id",entity.entityId()).put("reservation_key",JdbcCatalogDayAnalysisReservations.key(category,evidence.original().day(),entity.entityId())).put("logical_key",selection.logicalKey()).put("generation",selection.generation()).put("intent_id",selection.intentId()==null?JdbcFrozenInputs.stableId("intent",selection.logicalKey()+":"+selection.generation()):selection.intentId()).put("trigger",selection.trigger().name().toLowerCase(Locale.ROOT)).put("entity_revision_before",selection.header().revision()).put("entity_revision_after",after).put("entity_generation_before",selection.header().generation()).put("entity_identity_hash",selection.header().identityHash()).put("closure_hash",evidence.original().closureHash()).put("grouping_hash",evidence.grouping().hash()).put("reserved_at",new DateTimeFormatterBuilder().appendInstant(6).toFormatter().format(now));
        var members=n.putArray("members");for(var member:entity.members().stream().sorted(Comparator.comparing(e->e.member().itemId())).toList()){var m=member.member();members.addObject().put("item_id",m.itemId()).put("run_id",m.runId()).put("source_id",m.sourceId()).put("root_id",m.rootId()).put("input_hash",member.inputHash()).put("body_hash",member.bodyHash()).put("fragment_result_hash",m.fragmentResultHash()).put("final_result_hash",m.finalResultHash()).put("member_revision",m.revision());}return parse(JdbcFrozenInputs.canonical(n));
    }
    public Stored append(Stored value){Objects.requireNonNull(value);if(!category.equals(value.category()))throw invalid();var old=lockAndRead(value.day(),value.entityId());if(old!=null)return old;storage.append(value.reservationKey(),value.json(),value.reservedAt());var written=lockAndRead(value.day(),value.entityId());if(written==null||!written.json().equals(value.json()))throw invalid();return written;}
    private Stored decode(JdbcCatalogDayAnalysisReservations.Raw raw,LocalDate day,String entity){if(raw==null)return null;var stored=parse(raw.json());if(!category.equals(stored.category())||!day.equals(stored.day())||!entity.equals(stored.entityId())||!raw.actedAt().equals(stored.reservedAt()))throw invalid();return stored;}
    static Stored parse(String raw){
        try{
            var n=CanonicalJson.parse(raw);if(CanonicalJson.bytes(n).length>JdbcCatalogDayAnalysisReservations.MAX_PAYLOAD)throw new GenerationFlowService.CapacityGuarded();var fields=Set.of("schema_version","category","business_date","entity_id","reservation_key","logical_key","generation","intent_id","trigger","entity_revision_before","entity_revision_after","entity_generation_before","entity_identity_hash","closure_hash","grouping_hash","reserved_at","members");WireValues.object(n,fields,fields);if(!"catalog-day-analysis-reservation-v1".equals(text(n,"schema_version")))throw invalid();String category=category(text(n,"category")),entity=WireValues.id(n.get("entity_id"),false),key=JdbcCatalogDayAnalysisReservations.key(category,WireValues.businessDate(n.get("business_date")),entity),logical=text(n,"logical_key");if(!key.equals(WireValues.sha256(n.get("reservation_key")))||logical.isBlank()||logical.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>4096)throw invalid();
            long generation=number(n,"generation"),before=number(n,"entity_revision_before"),after=number(n,"entity_revision_after"),previous=number(n,"entity_generation_before");String trigger=text(n,"trigger");if(generation<1||before>=CanonicalJson.MAX_SAFE_INTEGER||after>=CanonicalJson.MAX_SAFE_INTEGER||!("new_entity".equals(trigger)?previous==0&&generation==1&&after==before+1&&CatalogDayAnalysisEligibilityService.logicalKey(category,entity).equals(logical):"version_recommended".equals(trigger)&&previous==generation&&after==before))throw invalid();if(!JdbcFrozenInputs.stableId("intent",logical+":"+generation).equals(WireValues.id(n.get("intent_id"),false)))throw invalid();for(String field:List.of("entity_identity_hash","closure_hash","grouping_hash"))WireValues.sha256(n.get(field));var time=WireValues.utcMicroseconds(n.get("reserved_at"));if(time.isBefore(WireValues.businessDate(n.get("business_date")).plusDays(1).atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant()))throw invalid();var values=n.get("members");if(!values.isArray()||values.isEmpty()||values.size()>100)throw invalid();var members=new ArrayList<Member>();String last=null;for(var value:values){var names=Set.of("item_id","run_id","source_id","root_id","input_hash","body_hash","fragment_result_hash","final_result_hash","member_revision");WireValues.object(value,names,names);String id=WireValues.id(value.get("item_id"),false);if(last!=null&&id.compareTo(last)<=0)throw invalid();last=id;long revision=number(value,"member_revision");if(revision<2||revision>=CanonicalJson.MAX_SAFE_INTEGER)throw invalid();members.add(new Member(id,WireValues.id(value.get("run_id"),false),WireValues.id(value.get("source_id"),true),WireValues.id(value.get("root_id"),false),WireValues.sha256(value.get("input_hash")),WireValues.sha256(value.get("body_hash")),WireValues.sha256(value.get("fragment_result_hash")),WireValues.sha256(value.get("final_result_hash")),revision));}return new Stored(n,members);
        }catch(GenerationFlowService.CapacityGuarded guarded){throw guarded;}catch(RuntimeException rejected){throw invalid();}
    }
    private static String category(String n){return switch(Objects.requireNonNull(n)){case "agent","skill","workflow","model"->n;default->throw invalid();};}
    private static String text(JsonNode n,String field){return WireValues.text(n.get(field));}private static long number(JsonNode n,String field){return WireValues.nonnegativeInteger(n.get(field));}
    private static IllegalStateException invalid(){return new IllegalStateException("original catalog day analysis reservation unavailable");}
}
